 scrollY_;   // a resize can clamp the view out from under an animation", "}", "", "// ?? Paint ??", "", "void EditorWidget::paintEvent(QPaintEvent* event) {", "    QPainter p(this);", "    p.setRenderHint(QPainter::TextAntialiasing);", "    p.setFont(font_);", "", "    // Only touch what was invalidated. A caret blink then costs one small", "    // rectangle instead of the entire viewport.", "    const QRect clip = event->rect();", "    p.fillRect(clip, Theme::EditorBg);", "", "    int startRow = std::max(0, (scrollY_ + clip.top()) / charHeight_);", "    int endRow = std::min((scrollY_ + clip.bottom()) / charHeight_ + 1, buffer_.lineCount());", "", "    // Code is clipped to its own column so horizontally scrolled text cannot", "    // bleed underneath the gutter.", "    p.save();", "    p.setClipRect(QRect(gutterWidth_, 0, std::max(0, width() - gutterWidth_), height()), Qt::IntersectClip);", "    paintCode(p, startRow, endRow);", "    paintCursor(p);", "    p.restore();", "", "    paintGutter(p, startRow, endRow);", "}", "", "void EditorWidget::paintGutter(QPainter& p, int startRow, int endRow) {", "    // The gutter shares the editor's surface ? no band, no rule.", "    p.fillRect(0, 0, gutterWidth_, height(), Theme::EditorBg);", "    p.setFont(font_);", "    for (int row = startRow; row < endRow; row++) {", "        int y = yFromRow(row);", "        p.setPen(row == cursor_.row ? Theme::TextSecondary : Theme::TextMuted);", "        QString num = QString::number(row + 1);", "        int x = gutterWidth_ - gutterPadding_ - p.fontMetrics().horizontalAdvance(num);", "        p.drawText(x, y + ascent_, num);", "    }", "}", "", "void EditorWidget::paintCode(QPainter& p, int startRow, int endRow) {", "    p.setFont(font_);", "", "    for (int row = startRow; row < endRow; row++) {", "        int y = yFromRow(row);", "", "        // Current line highlight", "        if (row == cursor_.row) {", "            p.fillRect(gutterWidth_, y, width() - gutterWidth_, charHeight_,